module TopModule (
    input  logic         clk,
    input  logic         load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    logic [15:0][15:0] grid;
    logic [15:0][15:0] next_grid;

    // Unpack q to a 2D grid for easier neighbor calculation
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                grid[r][c] = q[r * 16 + c];
            end
        end
    end

    // Compute next state for each cell on the toroid grid
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                int r_up, r_down, c_left, c_right;
                int neighbors;

                r_up    = (r == 0) ? 15 : r - 1;
                r_down  = (r == 15) ? 0 : r + 1;
                c_left  = (c == 0) ? 15 : c - 1;
                c_right = (c == 15) ? 0 : c + 1;

                neighbors = grid[r_up][c_left] +
                            grid[r_up][c] +
                            grid[r_up][c_right] +
                            grid[r][c_left] +
                            grid[r][c_right] +
                            grid[r_down][c_left] +
                            grid[r_down][c] +
                            grid[r_down][c_right];

                if (neighbors == 3) begin
                    next_grid[r][c] = 1'b1;
                end else if (neighbors == 2) begin
                    next_grid[r][c] = grid[r][c];
                end else begin
                    next_grid[r][c] = 1'b0;
                end
            end
        end
    end

    // Synchronous state update with active-high load
    always_ff @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (int r = 0; r < 16; r++) begin
                for (int c = 0; c < 16; c++) begin
                    q[r * 16 + c] <= next_grid[r][c];
                end
            end
        end
    end

endmodule

